        jdbc.update("INSERT INTO brake_command (command_code, warning_id, crane_code, zone_code, "
                        + "issued_at, created_at) VALUES (?,?,?,?,?,?)",
                commandCode, w.id(), w.craneCode(), w.zoneCode(),
