 */
private boolean isAuthorized(String craneCode, String zoneCode, Instant ts) {
    Integer hit = jdbc.queryForObject(
            "SELECT COUNT(1) FROM zone_authorization "
                    + "WHERE crane_code = ? AND zone_code = ? AND result = 'GRANTED' "
                    + "AND start_time <= ? AND end_time >= ?",
            Integer.class, craneCode, zoneCode, Timestamp.from(ts), Timestamp.from(ts));
    return hit != null && hit > 0;
}

