        // 持续 3 秒（第 4 个连续越限点）→ 制动
        PoseAcceptance a3 = poseProcessingService.ingest(pose("C-101", "2026-09-25T10:00:03Z", "Z-A1"));
        assertThat(a3.warningsGenerated()).isEmpty();
        assertThat(a3.brakesIssued()).hasSize(1);

